#!/bin/bash

delay_seconds="$1"
timer_id="$2"
bundle_id="$3"

if [[ ! "$timer_id" =~ ^[0-9]+$ || ! "$delay_seconds" =~ ^[0-9]+([.][0-9]+)?$ ]]; then
    exit 1
fi

/bin/sleep "$delay_seconds"

# The timer ID and bundle ID are generated by the workflow and contain only
# URL-safe characters. Alfred performs the notification and Large Type output.
/usr/bin/open -g "alfred://runtrigger/${bundle_id}/show_message/?argument=${timer_id}"
